#include "CaptureStrategy.h"
#include "screen/AreaSelector.h"
#include "capture/CaptureGeometry.h"
#include "capture/OverlayAnnotations.h"
#include "core/FileNames.h"
#include "core/Settings.h"

#include <QClipboard>
#include <QDateTime>
#include <QDebug>
#include <QDir>
#include <QFileDialog>
#include <QGuiApplication>
#include <QScreen>
#include <QWindow>

namespace Capture {

// This file provides the implementation for the CaptureStrategy base class
// The signals are automatically generated by Qt's MOC system

QPixmap CaptureStrategy::cropWithAnnotations(const QPixmap &shot, const QRect &virtualGeometry,
                                             const QRect &area,
                                             const QSharedPointer<OverlayAnnotations> &annotations)
{
    if (annotations && annotations->hasItems())
        return annotations->flattenedCrop(area);
    return cropVirtualArea(shot, virtualGeometry, area);
}

void CaptureStrategy::emitSelection(const QPixmap &shot, const QRect &virtualGeometry,
                                    const QRect &area,
                                    const QSharedPointer<OverlayAnnotations> &annotations)
{
    const QPixmap cropped = cropVirtualArea(shot, virtualGeometry, area);
    if (cropped.isNull()) {
        emit screenshotFailed("Invalid area selected or no screenshot available");
        return;
    }
    emit screenshotReady(cropped, annotations && annotations->hasItems()
                                      ? annotations->snapshot(area) : Editor::AnnotationSet{});
}

QSharedPointer<OverlayAnnotations> CaptureStrategy::attachAnnotations(
    const QList<Screen::AreaSelector*> &selectors, const QPixmap &frame, const QRect &virtualGeometry)
{
    if (!quickActionsEnabled())
        return {};
    // deleteLater: the last reference can drop inside one of the session's own signals.
    QSharedPointer<OverlayAnnotations> session(new OverlayAnnotations(frame, virtualGeometry),
                                               &QObject::deleteLater);
    for (Screen::AreaSelector *selector : selectors)
        selector->setLayer(session);
    return session;
}

void CaptureStrategy::showAreaSelector(const QPixmap &frame, const QRect &virtualGeometry)
{
    qDebug() << "Showing area selector, virtual geometry:" << virtualGeometry
             << "frame:" << frame.size() << "DPR:" << frame.devicePixelRatio();

    auto *selectors = new QList<Screen::AreaSelector*>();
    for (QScreen *screen : QGuiApplication::screens()) {
        const QRect screenGeometry = screen->geometry();
        auto *selector = new Screen::AreaSelector();
        selector->setScreenshot(frame);
        selector->setVirtualGeometry(virtualGeometry);
        selector->setScreenOffset(screenGeometry.topLeft());
        selector->setActionsEnabled(quickActionsEnabled());

        selector->setGeometry(screenGeometry);
        selector->setWindowState(Qt::WindowFullScreen);
        selector->winId(); // ensure the native window exists before placing it
        if (QWindow *window = selector->windowHandle())
            window->setScreen(screen);
        selector->showFullScreen();

        selectors->append(selector);
    }

    const auto annotations = attachAnnotations(*selectors, frame, virtualGeometry);

    for (auto *selector : *selectors) {
        // Each handler copies the session first: teardown disconnects its own lambda.
        connect(selector, &Screen::AreaSelector::areaSelected,
                this, [this, selectors, frame, virtualGeometry, annotations](const QRect &area) {
            const auto session = annotations;
            tearDownSelectors(selectors);
            if (area.isEmpty()) {
                qDebug() << "Area selection cancelled";
                emit screenshotCancelled();
                return;
            }
            emitSelection(frame, virtualGeometry, area, session);
        });
        connect(selector, &Screen::AreaSelector::copyRequested,
                this, [this, selectors, frame, virtualGeometry, annotations](const QRect &area) {
            const auto session = annotations;
            tearDownSelectors(selectors);
            copyAreaToClipboard(frame, virtualGeometry, area, session);
        });
        connect(selector, &Screen::AreaSelector::saveRequested,
                this, [this, selectors, frame, virtualGeometry, annotations](const QRect &area) {
            const auto session = annotations;
            // Teardown first, or the save dialog opens behind the overlay.
            tearDownSelectors(selectors);
            saveAreaToFile(frame, virtualGeometry, area, session);
        });
    }
}

void CaptureStrategy::tearDownSelectors(QList<Screen::AreaSelector*> *selectors)
{
    for (auto *selector : *selectors) {
        selector->blockSignals(true);
        selector->disconnect();
        selector->close();
        selector->deleteLater();
    }
    delete selectors;
}

void CaptureStrategy::copyAreaToClipboard(const QPixmap &shot, const QRect &virtualGeometry,
                                          const QRect &area,
                                          const QSharedPointer<OverlayAnnotations> &annotations)
{
    const QPixmap cropped = cropWithAnnotations(shot, virtualGeometry, area, annotations);
    if (cropped.isNull())
        return;

    QGuiApplication::clipboard()->setPixmap(cropped);
    qDebug() << "Selection copied to clipboard:" << cropped.size();
}

void CaptureStrategy::saveAreaToFile(const QPixmap &shot, const QRect &virtualGeometry,
                                     const QRect &area,
                                     const QSharedPointer<OverlayAnnotations> &annotations)
{
    const QPixmap cropped = cropWithAnnotations(shot, virtualGeometry, area, annotations);
    if (cropped.isNull())
        return;

    // The overlay is already torn down, so this dialog isn't hidden behind it.
    const QString dir = Core::Settings::screenshotFolder();
    QDir().mkpath(dir);
    const QString fileName = QFileDialog::getSaveFileName(
        nullptr, "Save Screenshot",
        dir + "/" + Core::screenshotFileName(QDateTime::currentDateTime(),
                                             Core::Settings::imageFormat()),
        "Image Files (*.png *.jpg *.bmp)");
    if (!fileName.isEmpty())
        cropped.save(fileName);
}

} // namespace Capture
